function cdqMarquerPdfOuvertV2269(id){
  if(String(utilisateurCourantRole||'')==='lecture')return;
  try{
    fichierOuvertPourModification=id;
    const meta=cdqDocumentMeta(id)||{};
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',String(meta.dateModification||''));
    sessionStorage.setItem('momentModification',String(Date.now()));
  }catch(_){}
}

window.addEventListener('message',function(e){
  if(!cdqFromPwa(e))return;
  const d=e.data||{};

  if(d.type==='CDQ_PDF_OPEN_INTERNAL_V2269'){
    if(!(d.blob instanceof Blob)||!d.fileId)return;
    const rec={
      id:String(d.fileId),
      nom:String(d.name||'Rapport.pdf'),
      blob:d.blob,
      taille:d.blob.size
    };
    cdqOpenPdfInternal(String(d.fileId),rec).catch(afficherErreur);
    return;
  }
});

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    if(navigator.onLine!==false && /Android/i.test(navigator.userAgent||'')){
      cdqMarquerPdfOuvertV2269(id);
      cdqPostToPwa({
        type:'CDQ_PDF_OPEN_REQUEST_V2269',
        requestId:'pdf-'+crypto.randomUUID(),
        fileId:String(id),
        name:String((meta&&meta.nom)||'Rapport.pdf'),
        reader:cdqPdfReaderPreference(),
        readOnly:String(utilisateurCourantRole||'')==='lecture'
      });
      afficherMessage('Choisissez le compte Google pour ouvrir le PDF.',true);
      return;
    }

    if(navigator.onLine!==false)return cdqV19OldModify(id);
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(!navigator.onLine){
    afficherMessage('Ouvrez ce fichier dans son application après l’avoir enregistré sur le téléphone.',false);
    return;
  }
  return cdqV19OldModify(id);
};

